-- CSE template (Sem 1 to 7). Sem 8 excluded.
-- choice_group: subjects sharing a group are alternatives/electives; CR keeps the ones that apply.
create table if not exists templates (
  id uuid primary key default gen_random_uuid(),
  course text not null,
  branch text not null,
  term_no int not null,
  term_name text not null,
  syllabus_version text,
  subjects jsonb not null,
  unique (course, branch, term_no, syllabus_version)
);

